import{_ as t,o,c as a,a3 as c}from"./chunks/framework.DAK02U1-.js";const p=JSON.parse('{"title":"Toolchain Structure","description":"","frontmatter":{"head":[["meta",{"property":"og:title","content":"Toolchain Structure | clice.io"}],["meta",{"property":"og:url","content":"https://docs.clice.io/xclang/design/toolchain"}],["meta",{"property":"og:image","content":"https://docs.clice.io/og.png"}],["meta",{"property":"og:image:width","content":"1200"}],["meta",{"property":"og:image:height","content":"630"}],["meta",{"property":"og:locale","content":"en_US"}],["link",{"rel":"canonical","href":"https://docs.clice.io/xclang/design/toolchain"}],["link",{"rel":"alternate","hreflang":"en","href":"https://docs.clice.io/xclang/design/toolchain"}],["link",{"rel":"alternate","hreflang":"x-default","href":"https://docs.clice.io/xclang/design/toolchain"}]]},"headers":[],"relativePath":"xclang/design/toolchain.md","filePath":"en/xclang/design/toolchain.md","lastUpdated":1791884712000}'),d={name:"xclang/design/toolchain.md"};function i(r,e,n,l,s,h){return o(),a("div",null,[...e[0]||(e[0]=[c('<h1 id="toolchain-structure" tabindex="-1">Toolchain Structure <a class="header-anchor" href="#toolchain-structure" aria-label="Permalink to &quot;Toolchain Structure&quot;">​</a></h1><p>How the pieces of a toolchain archive fit together, and why.</p><h2 id="summary" tabindex="-1">Summary <a class="header-anchor" href="#summary" aria-label="Permalink to &quot;Summary&quot;">​</a></h2><p>clang finds each target&#39;s sysroot and runtimes through a config file per target, not through defaults built into the compiler. clang, lld and most tools are one program. The sysroots are plain directories that any clang can use. For users, that means <code>--target</code> is the whole difference between a native and a cross build, <code>-stdlib=platform</code> the switch to the platform&#39;s C++ library, and <code>--no-default-config</code> gives back a bare, upstream-like clang.</p><h2 id="a-config-file-per-target" tabindex="-1">A Config File per Target <a class="header-anchor" href="#a-config-file-per-target" aria-label="Permalink to &quot;A Config File per Target&quot;">​</a></h2><p>clang reads a config file for the target it compiles for. For <code>--target=aarch64-w64-mingw32</code>, it looks for <code>aarch64-w64-windows-gnu.cfg</code> next to its own program. That name is clang&#39;s normalized spelling of the triple. clang puts the options in the file before those of the command line. xclang writes one file per target, and per spelling of it, into <code>bin/</code>:</p><table tabindex="0"><thead><tr><th>target</th><th>config files</th></tr></thead><tbody><tr><td>Linux</td><td><code>&lt;arch&gt;-unknown-linux-gnu.cfg</code>, <code>&lt;arch&gt;-pc-linux-gnu.cfg</code></td></tr><tr><td>Linux (musl)</td><td><code>&lt;arch&gt;-unknown-linux-musl.cfg</code>, <code>&lt;arch&gt;-pc-linux-musl.cfg</code></td></tr><tr><td>Windows (MinGW)</td><td><code>&lt;arch&gt;-w64-windows-gnu.cfg</code>, <code>&lt;arch&gt;-pc-windows-gnu.cfg</code></td></tr><tr><td>macOS</td><td><code>&lt;arch&gt;-apple-darwin.cfg</code>, <code>&lt;arch&gt;-apple-macos.cfg</code>, <code>&lt;arch&gt;-apple-macosx.cfg</code></td></tr><tr><td>Windows (MSVC)</td><td><code>&lt;arch&gt;-pc-windows-msvc.cfg</code>, <code>&lt;arch&gt;-unknown-windows-msvc.cfg</code>, and for clang-cl <code>&lt;spelling&gt;-clang-cl.cfg</code></td></tr></tbody></table><p><code>&lt;arch&gt;</code> is <code>x86_64</code>, or for arm64 both <code>aarch64</code> and <code>arm64</code>, Apple&#39;s and Microsoft&#39;s name, which clang takes for every target: <code>arm64-linux-gnu</code>, <code>arm64-w64-mingw32</code> and <code>arm64-pc-windows-msvc</code> read the files of the aarch64 targets (from 23.1.3.1 on; macOS&#39;s always), and the Linux and MinGW ones find their compiler-rt with <a href="./../reference/patches">patch 0013</a>.</p><p>Each says this (<a href="https://github.com/clice-io/xclang/tree/main/toolchain/config" target="_blank" rel="noreferrer">toolchain/config/</a>):</p><table tabindex="0"><thead><tr><th>target</th><th>options</th></tr></thead><tbody><tr><td>Linux</td><td><code>--sysroot</code> of the target, <code>-rtlib=compiler-rt -unwindlib=libunwind -stdlib=libc++</code>, <code>-static-libstdc++ -static-libgcc</code>, <code>-fuse-ld=lld</code></td></tr><tr><td>Linux (musl)</td><td>the same, and <code>-static</code>: musl is linked in too (<a href="./../reference/targets#musl-targets">musl targets</a>)</td></tr><tr><td>Windows (MinGW)</td><td><code>--sysroot</code> of the target, <code>-rtlib=compiler-rt -unwindlib=libunwind -stdlib=libc++</code>, <code>-fuse-ld=lld</code>; the sysroot has static libraries only</td></tr><tr><td>macOS</td><td>xclang&#39;s libc++ headers (<code>-stdlib++-isystem</code>) and <code>libc++.a</code> ahead of the SDK&#39;s <code>libc++.tbd</code> (<code>-L</code>), <code>-mmacos-version-min=13.0</code>, <code>-fuse-ld=lld</code></td></tr><tr><td>Windows (MSVC)</td><td><code>@&lt;target&gt;-sdk.cfg</code>, which includes the file of the SDK in use that names it, from <code>sdk/windows</code>; on Linux and macOS hosts <code>sdk/windows</code> as the sysroot; xclang&#39;s libc++ headers (<code>-stdlib++-isystem</code>); <code>-fuse-ld=lld</code>; the builtins and the hybrid CRT named in every object (<a href="./windows#msvc-targets">MSVC targets</a>)</td></tr></tbody></table><p>Paths are relative to the file (<code>&lt;CFGDIR&gt;</code>), so the toolchain directory works wherever it is unpacked. The config files apply to native builds too. A plain <code>clang++ main.cpp</code> on Linux compiles against glibc 2.17, not the machine&#39;s glibc, and links everything but glibc statically.</p><h3 id="the-platform-s-c-library" tabindex="-1">The Platform&#39;s C++ Library <a class="header-anchor" href="#the-platform-s-c-library" aria-label="Permalink to &quot;The Platform&#39;s C++ Library&quot;">​</a></h3><p>Every one of these files has a second one, <code>&lt;spelling&gt;-system.cfg</code> (and <code>&lt;spelling&gt;-clang-cl-system.cfg</code>), for the platform&#39;s C++ library. A <code>-stdlib=</code> of another library than libc++, <code>platform</code> or <code>libstdc++</code>, makes clang read it in place of the first (<a href="./../reference/patches">patch 0018</a>); clang-cl takes <code>/clang:-stdlib=platform</code>. It holds what the target needs besides xclang&#39;s C++ library and sysroot:</p><table tabindex="0"><thead><tr><th>target</th><th><code>&lt;spelling&gt;-system.cfg</code></th></tr></thead><tbody><tr><td>Linux, Linux (musl), Windows (MinGW)</td><td><code>-fuse-ld=lld</code>. The platform&#39;s library comes with a sysroot of its own: the host&#39;s, a distribution&#39;s cross packages, or that of <code>--sysroot</code></td></tr><tr><td>macOS</td><td>the SDK, <code>-mmacos-version-min=13.0</code>, <code>-fuse-ld=lld</code>: the SDK&#39;s libc++</td></tr><tr><td>Windows (MSVC)</td><td>the target&#39;s file without xclang&#39;s libc++: Microsoft&#39;s STL, from the same SDK or Visual Studio</td></tr></tbody></table><p>The switch picks a file, as nothing after a config file can take back what it gave. <code>-stdlib++-isystem</code> stands for the C++ library&#39;s headers whatever <code>-stdlib=</code> says, a macOS <code>-L</code> finds <code>libc++.a</code> before the SDK&#39;s <code>libc++.tbd</code>, and the Linux sysroot has no libstdc++ (<a href="./../integrations/clang#the-system-s-c-library">the system&#39;s C++ library</a>).</p><h3 id="why-not-built-in-defaults" tabindex="-1">Why Not Built-In Defaults <a class="header-anchor" href="#why-not-built-in-defaults" aria-label="Permalink to &quot;Why Not Built-In Defaults&quot;">​</a></h3><p>clang can be built with defaults instead (<code>CLANG_DEFAULT_CXX_STDLIB</code>, <code>CLANG_DEFAULT_RTLIB</code>, <code>CLANG_DEFAULT_LINKER</code>, ...), and 23.1.2.1 was. Those defaults live in the clang driver, which is also in libclang. Tools built on libclang run the driver to understand other compilers&#39; commands.</p><p>clice does exactly that. Given a <code>g++</code> command from a compilation database, it runs the clang driver in place of g++ to find the include paths. With the defaults built in, that <code>g++</code> command got the headers of libc++ instead of libstdc++.</p><p>Since 23.1.2.2 the defaults are gone, and the config files carry them, so no default needs a patched driver. <code>clang</code> from <code>bin/</code> reads the file for its target. The driver inside libclang has no <code>bin/</code> and no config file, so it behaves like upstream clang.</p><h3 id="the-bare-compiler" tabindex="-1">The Bare Compiler <a class="header-anchor" href="#the-bare-compiler" aria-label="Permalink to &quot;The Bare Compiler&quot;">​</a></h3><p>The same separation gives the bare compiler back on demand. <code>--no-default-config</code> skips the config file. clang then builds against the system&#39;s own headers and libraries, as upstream clang would, and links with the system&#39;s linker. <code>-stdlib=platform</code> does the same with lld, and for the vendor SDKs too.</p><h3 id="two-details" tabindex="-1">Two Details <a class="header-anchor" href="#two-details" aria-label="Permalink to &quot;Two Details&quot;">​</a></h3><ul><li><strong>clang-cl targets MSVC.</strong> clang-cl looks for <code>&lt;default target&gt;-clang-cl.cfg</code>, then <code>&lt;default target&gt;.cfg</code>, before it turns to the MSVC target. So it read the MinGW options of the host and warned about each. An empty <code>&lt;spelling&gt;-clang-cl.cfg</code> for every spelling stops that, since 23.1.2.3. Since 23.1.2.7, with the MSVC targets, that file is the clang-cl file of the MSVC target of its architecture.</li><li><strong>Bazel uses its own copy.</strong> clang makes the directory of a config file absolute, and Bazel needs no absolute paths in the outputs of its actions; the dependency files would name the sandbox. The Bazel module writes each config file again with paths relative to the execution root (<a href="./bazel-module#no-absolute-paths">no absolute paths</a>).</li></ul><h2 id="one-program" tabindex="-1">One Program <a class="header-anchor" href="#one-program" aria-label="Permalink to &quot;One Program&quot;">​</a></h2><p>clang, lld and most tools (<code>llvm-ar</code>, <code>llvm-objcopy</code>, <code>dsymutil</code>, <code>llvm-gsymutil</code>, ...) are one program, <code>llvm</code>, built with LLVM&#39;s <code>LLVM_TOOL_LLVM_DRIVER_BUILD</code>. Each name is a link to it, or on Windows a small <a href="./windows#the-launchers">launcher</a>. The program dispatches on the name it was started by. Otherwise every tool carries its own copy of the LLVM libraries.</p><p>When xclang switched to it, the archives shrank:</p><table tabindex="0"><thead><tr><th>host</th><th>before</th><th>after</th></tr></thead><tbody><tr><td>Linux x64</td><td>148 MB</td><td>83 MB</td></tr><tr><td>Linux arm64</td><td>133 MB</td><td>77 MB</td></tr><tr><td>macOS arm64</td><td>154 MB</td><td>100 MB</td></tr><tr><td>macOS x64</td><td>172 MB</td><td>110 MB</td></tr><tr><td>Windows x64</td><td>540 MB (a zip)</td><td>82 MB</td></tr><tr><td>Windows arm64</td><td>521 MB (a zip)</td><td>74 MB</td></tr></tbody></table><p>Not all of it came from the one program. The same change dropped the locale archive of the Linux sysroots and turned on identical code folding. The Windows archives also changed from zip to <code>.tar.xz</code>.</p><p>A shared <code>libLLVM</code> would also have shared the code. It was rejected for speed: calls into it go through the tables of the dynamic linker, and ThinLTO cannot optimize across its boundary.</p><p>Some tools are outside the one program, built on their own: <code>llvm-profdata</code>, <code>llvm-cov</code>, <code>llvm-dwarfdump</code>, <code>llvm-strings</code> and <code>FileCheck</code>.</p><h3 id="what-prints" tabindex="-1">What <code>-###</code> Prints <a class="header-anchor" href="#what-prints" aria-label="Permalink to &quot;What `-###` Prints&quot;">​</a></h3><p>A tool that reads the output of <code>clang -###</code> sees a consequence. clang prints its compile job like this:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>&quot;/path/xclang/bin/llvm&quot; &quot;clang&quot; &quot;-cc1&quot; ...</span></span></code></pre></div><p>It does not print <code>&quot;/path/xclang/bin/clang&quot; &quot;-cc1&quot; ...</code>. The driver runs the job as the program it is in, with the tool name as the first argument. A parser that expects <code>-cc1</code> as the second word has to skip the name. clice met this in its first build with xclang and handles both forms.</p><h2 id="plain-directories" tabindex="-1">Plain Directories <a class="header-anchor" href="#plain-directories" aria-label="Permalink to &quot;Plain Directories&quot;">​</a></h2><p>A sysroot is laid out the way the clang drivers expect, with libc++, libunwind and the <a href="./hermeticity#gcc-library-names">GCC library names</a> in it. compiler-rt is in the clang resource directory (<a href="./../reference/layout">archive layout</a>). The sysroots hold what compiling and linking read, nothing else: headers, startup files and libraries, not glibc&#39;s programs, locales or gconv modules.</p><p>Nothing in them is specific to xclang&#39;s clang. Any clang of the same major version, pointed at a sysroot with <code>--sysroot</code> and at the resource directory with <code>-resource-dir</code>, cross-compiles with it. The config files are plain text, so anyone can read what a target means.</p>',37)])])}const f=t(d,[["render",i]]);export{p as __pageData,f as default};
